window.LD=window.LD||{};window.LD["hero/h19"]={"id":"h19","name":"Christian","owner":"Christian","npc":false,"pronoun":"he","cls":"armorer","title":"Armorer","level":11,"look":{"skin":"#e8b088","hair":"#efe2c0","style":2,"face":1,"fav":"#2b2b33","fav_name":"black","scars":[]},"pet":null,"mount":null,"alive":true,"keepsake":"Ironroot, grandmother's mace","maps":[{"dungeon":"ashveil_crypts","pct":40,"worked":13}],"party":"p2","party_name":"The Verdant Sigil","loc":"bleakmarsh","loc_name":"Bleakmarsh","travel":null,"rep":{"thornwall":4,"ashfen":3},"curse":null,"fstanding":{"scale":14.0,"dawn":14.0,"collegium":2.0,"fellowship":-4.0,"thorns":-0.5},"faction":null,"frank":0,"doing":"hunting in Bleakmarsh","why":"paid to clear 10 will-o'-wisps out of Bleakmarsh","delve":{"now":null,"last":{"dest":"ashveil_crypts","day":22,"days":7,"why":"after the boss: about 21 silver a day each, risk slight; the season goal: to earn 1,150 silver between them before the season ends","packed":{"torches":33,"rations":33},"turn":"their nerves were fraying","rooms":13}},"route":"Day 26: spent the day in Bleakmarsh.","today":["Fought 1 fight: won 1; 1 foe down.","+271 XP.","Came away with a bottle of wisplight.","Stress: −4 a day's hunting, +2 camping out, +1 an easy fight, −1 good company, −1 a good camp supper."],"fights_today":["f64"],"tables_today":[{"table":"Walking-Cap Ragout","game":"m80","route":"meal"}],"daybook":{"day":26,"label":"Day 26","title":"Season 1, day 26, hour by hour","blocks":[{"act":"hunt","label":"Reading the ground","from":6.0,"to":8.0,"line":"Christian finds the second print a yard on, and calls Echo over. Echo kneels over a line of prints at the edge of Bleakmarsh and reads them like a notice: one animal, heavy, not hurrying.","stretch":"sign","biome":"marsh","weather":"cloudy","crew":["h19","h6","h11"],"event":"seed_sign_tracks","test":"good"},{"act":"hunt","label":"Reading the ground","from":8.0,"to":10.0,"line":"Christian keeps low and still so no shadow falls where Echo is reading. A scatter of crows over the next rise tells Echo what the ground has not. Something dead, or something about to be.","stretch":"sign","biome":"marsh","weather":"cloudy","crew":["h19","h6","h11"],"event":"hs_track_crows","test":"good"},{"act":"hunt","label":"The quarry turns","from":10.0,"to":12.0,"line":"Christian matches Echo step for step, setting each foot where the last one was. The island of dry ground in the reeds is exactly where the villagers told Echo. So are the things on it: the corpse-lights. It takes longer than anyone would like. 2 Will-o'-Wisps down in the end, and nobody worse than scratched.","stretch":"stalk","biome":"marsh","weather":"cloudy","crew":["h19","h6","h11"],"event":"hf_clear_marsh","fought":true,"fights":["f64"]},{"act":"hunt","label":"The stalk","from":12.0,"to":13.0,"line":"Christian holds his breath as long as Echo does, then a little longer. Echo takes a game trail through the brush, no wider than a hand, and follows it as the animals do: low, steady, and without once looking up. It brings her out within a spear-length of the herd.","stretch":"stalk","biome":"marsh","weather":"cloudy","crew":["h19","h6","h11"],"event":"hk_follow_the_run","test":"good"},{"act":"hunt","label":"The quarry","from":13.0,"to":14.0,"line":"Christian works round behind it, slow as a shadow, to push it on. Echo drops a fat duck into the sedge, and wades in to find it. A ration, still warm, and not worth the wet boots, and entirely worth it.","stretch":"quarry","biome":"marsh","weather":"cloudy","crew":["h19","h6","h11"],"event":"hv_bm_duck","test":"good"},{"act":"hunt","label":"The quarry","from":14.0,"to":16.0,"line":"Christian lies in wait at the far end of the run, where it has to come out. A slow dark shape in the pool, a quick hand on the pole: Echo lifts out a fish and holds it up for the trees to admire.","stretch":"quarry","biome":"marsh","weather":"cloudy","crew":["h19","h6","h11"],"event":"hq_eel_spear","test":"good"},{"act":"hunt","label":"Dressing the kill","from":16.0,"to":17.0,"line":"Christian cleans and joints the small game on a flat stone and threads it on green sticks for the fire, and keeps a ration back for tomorrow.","stretch":"dress","biome":"marsh","weather":"cloudy","crew":["h19","h6","h11"],"event":"hc_dress_sticks"},{"act":"hunt","label":"Foraging","from":17.0,"to":18.0,"line":"Christian picks alongside Natasha, slower and choosier. Natasha kneels in the bog and gathers cranberries one at a time from the moss, until her knees are as wet as the berries.","stretch":"forage","biome":"marsh","weather":"cloudy","crew":["h19","h6","h11"],"event":"ho_bog_cranberries"}],"evening":{"kind":"camp","line":"Camped out in Bleakmarsh","more":[{"table":"Walking-Cap Ragout","game":"m80","route":"meal"}]},"wday":26},"grew":[],"progress":"day 1 of 7","goal":{"text":"to earn 1,150 silver between them before the season ends","kind":"purse","done":null,"progress":"332 of 1,150 silver","missed":false,"crew":"The Verdant Sigil","party":"p2"},"vows":[],"renown":168,"epithet":null,"gold":53,"copper":1,"hp":140,"maxhp":140,"injuries":[],"legend":false,"weapon":"mace","weapon_tier":2,"armor":"chain","armor_tier":1,"kit":{"weapon":{"family":"mace","tier":2,"two":false,"glow":null},"offhand":{"art":"hammer","tier":1,"glow":null},"armor":{"material":"chain","tier":1,"outfit":"chain","glow":null},"head":{"art":"circlet","tier":3,"glow":"#c8e8ff"},"back":null,"neck":null,"rings":[],"pocket":null,"belt":null,"boots":null,"gloves":null,"mark":null},"vox":{"bold":1.0,"style":"direct"},"jail":0,"away":false,"died_day":null,"died_season":null,"died_sday":null,"joined":1,"lodging":"common","power":164,"home":null,"sleep":{"setting":"camp","place":"Camped out at Bleakmarsh"},"dream":"to hold a record in the Creel Book","trophies":[{"boss":"Gruk the Warchief","monster":"goblin_warchief","gen":1,"role":null,"place":"Goblin Camp","day":9,"season":1,"fight":"f25","with":"The Verdant Sigil"}],"cabinet":[],"stats":{"might":17,"agility":8,"mind":12,"grit":12,"heart":9},"eff":{"might":17,"agility":8,"mind":14,"grit":12,"heart":10},"traits":{"boldness":1.0,"risk":-0.04,"greed":0.18,"sociability":-0.04,"honor":0.16,"curiosity":-0.15,"temper":0.04,"loyalty":0.09},"aff":{"travel":1.0,"crit":1.4,"stealth":0.3,"beast":0.1,"craft":6.8,"guard":0.0,"holy":1.4,"arcane":1.0,"lore":1.0,"heal":0.0,"trade":0.3,"hunt":0.4,"fate":0.2,"death":0.6,"nature":0.2},"lean_aff":{"travel":0.3,"crit":1.1,"stealth":0.2,"beast":0.1,"craft":6.5,"guard":0.0,"holy":1.2,"arcane":1.0,"lore":1.0,"heal":0.0,"trade":0.1,"hunt":0.6,"fate":0.1,"death":0.3,"nature":0.4},"growth":{"might":2.9499999999999997,"agility":1.0,"mind":1.45,"grit":1.6,"heart":1.0},"skills":[{"id":"smith_hands","rank":1,"name":"Smith's Hands","desc":"Fixes and upgrades their own gear.","tags":["craft"],"type":"world","uses":0,"school":"craft","side":false,"own":true,"keystone":null},{"id":"almsgiver","rank":1,"name":"Almsgiver","desc":"Never passes a beggar's bowl.","tags":["holy"],"type":"world","uses":0,"school":"holy","side":false,"own":false,"keystone":null},{"id":"local_history","rank":1,"name":"Local History","desc":"Knows who built the bridge, and who fell off it.","tags":["lore","arcane"],"type":"world","uses":0,"school":"lore","side":false,"own":false,"keystone":null},{"id":"hammer_down","rank":1,"name":"Hammer Down","desc":"Forging technique, applied to faces.","tags":["craft"],"type":"attack","uses":6,"school":"craft","side":false,"own":false,"keystone":null},{"id":"carpenter","rank":2,"name":"Carpentry","desc":"Measures twice, cuts once, builds a bench.","tags":["craft"],"type":"world","uses":0,"school":"craft","side":false,"own":true,"keystone":null},{"id":"disarm","rank":1,"name":"Disarm","desc":"A twist of the wrist and their sword is on the floor.","tags":["crit"],"type":"attack","uses":1,"school":"blade","side":false,"own":false,"keystone":null},{"id":"firekeeper","rank":1,"name":"Firekeeper","desc":"Lights a fire in a rainstorm, with wet wood, every time.","tags":[],"type":"world","uses":0,"school":"hearth","side":true,"own":false,"keystone":null},{"id":"tailor","rank":1,"name":"Needle and Thread","desc":"Mends cloaks, patches tents, takes in trousers.","tags":["craft"],"type":"world","uses":0,"school":"craft","side":false,"own":false,"keystone":null},{"id":"anvil_drop","rank":1,"name":"Anvil Drop","desc":"Brought the anvil. Nobody asked why. Now they know.","tags":["craft"],"type":"attack","uses":1,"school":"craft","side":false,"own":true,"keystone":null},{"id":"hammer_and_hold","rank":1,"name":"Hammer and Hold","desc":"Bangs the dents out of everyone's armour without leaving the line.","tags":[],"type":"trigger","uses":0,"school":null,"side":false,"own":false,"keystone":10,"does":"When he drops low in a fight, he hammers a dent out of every ally's armour on the spot."},{"id":"whetstone","rank":1,"name":"Whetstone","desc":"Sharpens everything. Has been asked to stop.","tags":["craft"],"type":"world","uses":0,"school":"blade","side":false,"own":true,"keystone":null}],"kit_items":[{"slot":"weapon","name":"Ironroot","art":"mace","tier":2,"gem":null,"tint":null,"glow":null,"magic":false,"enchant":null,"desc":"","fx":"","story":"Grandmother's mace, carried from home","day":1,"history":[{"day":11,"text":"Re-forged a tier up by Dagny in Thornwall, with grandmother's name left on it"}],"plus":"hits harder on every blow (+10 power)"},{"slot":"armor","name":"Rusty Mail","art":"chain","tier":1,"gem":null,"tint":null,"glow":null,"magic":false,"enchant":null,"desc":"","fx":"","story":null,"day":null,"history":[],"plus":"harder to hurt (+5 armour)"},{"slot":"offhand","name":"Smith's Hammer","art":"hammer","tier":1,"gem":null,"tint":null,"glow":null,"magic":false,"enchant":null,"desc":"","fx":"Hits a little harder (+1% power), better at mending gear","story":"A gift from the guild on his new calling","day":19,"history":[],"plus":null},{"slot":"head","name":"Circlet of the Clear Head","art":"circlet","tier":null,"gem":null,"tint":"#c0c8d8","glow":"#c8e8ff","magic":true,"enchant":null,"desc":"A thin silver band worn by an abbess who settled every dispute in her valley. Its wearer thinks clearly, speaks kindly, and does not get headaches.","fx":"Sharper, more charming","story":"Found on floor 2 of Goblin Camp, by Christian","day":8,"history":[{"day":8,"text":"Found on floor 2 of Goblin Camp, by Christian"},{"day":11,"text":"Named by Sister Amberline"},{"day":11,"text":"First worn by Christian"}],"plus":null}],"row":"front","curios":[],"sets":[{"name":"Button Checkers","kind":"checkers","tier":0,"art":"button","desc":"Twenty-four coat buttons and a chalked cloth, which is how half of Thornwall learned to jump.","look":"Mismatched coat buttons, bone and brass, on a chalked cloth board scuffed to the colour of porridge","condition":"like new","missing":0,"games":0,"story":"Bought in Ashfen for 1 silver 6 copper","history":[{"day":25,"text":"Bought in Ashfen for 1 silver 6 copper, by Christian"}]}],"h2h":{"rows":[],"prefs":{"cards":0.1027,"dice":0.2688,"checkers":0.2806,"chess":0.1933,"tarot":0.1547},"nicks":{}},"pastimes":{"keen":{"sing":0.136,"play":0.057,"cook":0.495,"fish":0.266,"game":0.743},"skill":{"sing":0.194,"play":0.0,"cook":0.175,"fish":0.0,"game":0.37}},"purse":[[2,300,{}],[3,230,{"rations":-20,"tavern":-20,"beds":-30}],[4,230,null],[5,310,{"loot":30,"town life":50}],[6,350,{"loot":40}],[7,350,{}],[8,570,{"treasure":220}],[9,950,{"loot":280,"boss":100}],[10,1050,{"maps sold":100}],[11,290,{"sales":130,"bounties":120,"rations":-100,"potions":-160,"gear":-520,"relics":-150,"tavern":-20,"beds":-30,"drinks":-30}],[12,23,{"rations":-200,"goods":-10,"sales":100,"readings":-7,"incidents":-140,"beds":-10}],[13,33,{"odd request":10}],[14,23,{"work":10,"beds":-20}],[15,43,{"odd request":20}],[16,43,{}],[17,43,{}],[18,43,{}],[19,43,{}],[20,43,{}],[21,453,{"treasure":410}],[22,453,{}],[23,733,{"sales":340,"tavern":-20,"beds":-40}],[24,627,{"food":-26,"training":-70,"beds":-10}],[25,531,{"sales":70,"hobbies":-16,"rations":-150}],[26,531,{}]],"music":{"band":0.194,"label":"dreadful","inst":[],"songs":[{"src":"folk","id":"footbridge_dance","title":"The Footbridge Dance","tone":"rowdy","meter":"4/4","bpm":112,"diff":2,"n":1},{"src":"book","id":"drinking_skeleton","title":"Drinking With the Skeleton","tone":"funny","meter":"6/8","bpm":117,"diff":4,"n":1},{"src":"folk","id":"washing_line","title":"The Washing-Line Jig","tone":"rowdy","meter":"6/8","bpm":116,"diff":2,"n":1}],"wrote":[],"played":0.75,"n":{"joined":3},"anthem":null,"moments":[],"lately":[{"id":"n20","day":22,"title":"The Footbridge Dance","src":"folk","role":"sing","outcome":"sweet","where":"camp","place":"camp in The Ashveil Crypts","lead":"h6"},{"id":"n14","day":19,"title":"Drinking With the Skeleton","src":"book","role":"sing","outcome":"rough","where":"camp","place":"camp in The Ashveil Crypts","lead":"h6"}]},"omens":{"active":[],"log":[{"rid":"r22","day":12,"card":"major_14_temperance","rev":false,"omen":"mending","hit":false,"by":"Sabine Venn"},{"rid":"r22","day":12,"card":"major_02_high_priestess","rev":false,"omen":"keen_eye","hit":false,"by":"Sabine Venn"},{"rid":"r22","day":12,"card":"cups_2","rev":false,"omen":"new_friend","hit":true,"by":"Sabine Venn"}],"reads":null},"table":{"favourite":"roast","favourite_name":"a proper roast","keeps_parts":true,"cook":0.3,"cooks":false,"dishes":[{"id":"cap_ragout","name":"Walking-Cap Ragout","n":2,"love":false},{"id":"eel_pie","name":"Eel Pie","n":1,"love":false},{"id":"fenmist_chowder","name":"Fen-Mist Chowder","n":1,"love":false},{"id":"river_cone","name":"Fried River Fish in a Paper Cone","n":1,"love":false},{"id":"toasted_cheese","name":"Toasted Cheese Trenchers","n":1,"love":false}],"recent":[{"day":26,"meal":"m80","dish":"cap_ragout","text":"Natasha cooks some Walking-Cap Ragout in Bleakmarsh while the rest pretend to keep watch. It stopped twitching the moment the garlic went in."},{"day":24,"meal":"m73","dish":"eel_pie","text":"Christian tastes an Eel Pie from Widow Marl, then from Tobin the eel-catcher, then from Widow Marl again to be sure, and names Tobin the eel-catcher the better. The other one takes it badly. (1 silver)"},{"day":24,"meal":"m72","dish":"river_cone","text":"Christian finds the Carrbridge cart at the Ashfen market and tries some Fried River Fish in a Paper Cone, a long way from home. It comes wrapped in last week's tariff notices. (8 copper)"},{"day":24,"meal":"m68","dish":"fenmist_chowder","text":"It's feast day in Ashfen, and Echo, Natasha and Christian eat some Fen-Mist Chowder at the long tables with half the town. It smells of smoke and the fen at dawn. (8 copper each)"},{"day":18,"meal":"m51","dish":"cap_ragout","text":"Christian lays out some Walking-Cap Ragout in the Ashveil Crypts on a flat stone, like a proper table. It is rich, dark and only slightly mobile."},{"day":17,"meal":"m42","dish":"victory_ham","text":"Gruk's Victory Ham in the Ashveil Crypts. Christian cooks it like a ceremony, and the crew eat it like one. It comes glazed on the warchief's own shield."},{"day":16,"meal":"m36","dish":"toasted_cheese","text":"Natasha's Toasted Cheese Trenchers in the Ashveil Crypts come out the wrong colour. They eat them anyway. That was a mistake."}],"knack":0.5,"cooked":[{"id":"cap_ragout","name":"Walking-Cap Ragout","n":1,"kind":"monster"},{"id":"victory_ham","name":"Gruk's Victory Ham","n":1,"kind":"legendary"}]},"angler":null,"next_class":{"level":18,"id":"ironclad","name":"Ironclad","alt":"Weaponwright","why":["crafting","holy work"]},"travellers":[["marigold","Marigold",1]],"goals_log":[],"vow_log":[],"letters":[{"day":7,"season":1,"text":"Report. Joined The Verdant Sigil in Thornwall. Went into Goblin Camp. Floor 1: 4 Goblins and a Giant Rat. Floor 2: 2 Goblins and a Goblin Shaman. Won both. Beat the dent out of Echo's helmet on a flat rock. Straightened my own bent sword with two rocks and some swearing, right there at Goblin Camp. Walked into a signpost in the fog in Ironhaven and apologised to it. Level 4. Nothing else worth saying. — Christian","voice":"direct"},{"day":14,"season":1,"text":"Report. Christian here. The Verdant Sigil took Gruk the Warchief at the bottom of Goblin Camp, and I took Echo's watch without being asked. Not worth a mention. In Thornwall the temple named my relic the Circlet of the Clear Head, and I settled the cooking rota in one sentence. In Carrbridge Sabine Venn read my cards for the first time, and a stranger sold me a treasure map to Frostspire for 14 silver. Might be real. Goal is 1,150 silver between us. The dragon of Emberdeep is still the plan. — Christian","voice":"direct"},{"day":21,"season":1,"text":"Plain account. Level 10 brought Hammer and Hold: when I drop low, I hammer the dents out of every ally's armour on the spot. The Ninth Step in the Ashveil Crypts caught me and cracked my collarbone. We kept at the second floor anyway: choir loft, funeral feast hall, Hammer Down. I tightened Natasha's strap mid-corridor. \"Here Comes Christian\" has reached Carrbridge, where half the names are wrong and the fight lasts twice as long. I tested my edge on a hair. The hair lost. That's the account. — Christian","voice":"direct"}],"voice":"direct","threads":[[{"id":"e210","day":9,"kind":"boss","text":"Down at the bottom of Goblin Camp, The Verdant Sigil slays Gruk the Warchief, a Goblin Archer and a Goblin. Echo's Pinning Shot dropped Gruk, Christian's Hammer Down tied him up, and Echo did the unglamorous work that kept the line from breaking. Loot: 6 goblin ears, 3 trinkets, Gruk's own smoked ham.","heroes":["h6","h11","h19"],"parties":["p2"],"fight":"f25"},{"id":"e228","day":9,"kind":"big_move","text":"Gruk the Warchief is down, and the table moves: Echo +56 renown (11th to 2nd), Christian +52 (10th to 3rd) and Natasha +51 (12th to 4th). The Verdant Sigil +107 party renown, 3rd to 1st among the crews.","heroes":["h6","h19","h11"],"parties":["p2"],"fight":"f25"}]],"renown_parts":[["levels",60],["bosses",30],["deeds and stories",28],["kills",19],["silver earned",17],["dungeon floors",8],["delves",5],["a steady hand",1]],"class_history":[[1,"warrior"],[19,"armorer"]],"gear":{"weapon":{"slot":"weapon","family":"mace","tier":2,"name":"Ironroot","kind":"melee","from":"Grandmother's mace, carried from home","day":1,"history":[{"day":11,"text":"Re-forged a tier up by Dagny in Thornwall, with grandmother's name left on it"}],"heirloom":{"name":"Ironroot","item":"mace"}},"armor":{"slot":"armor","family":"chain","tier":1,"name":"Rusty Mail"},"offhand":{"slot":"offhand","family":"hammer","tier":1,"name":"Smith's Hammer","from":"A gift from the guild on his new calling","day":19},"head":{"slot":"head","magic":"clear_head_circlet","name":"Circlet of the Clear Head","identified":true,"found_day":8,"value":220,"mods":{"mind":2,"heart":1},"from":"Found on floor 2 of Goblin Camp, by Christian","day":8,"history":[{"day":8,"text":"Found on floor 2 of Goblin Camp, by Christian"},{"day":11,"text":"Named by Sister Amberline"},{"day":11,"text":"First worn by Christian"}]},"back":null,"neck":null,"ring1":null,"ring2":null,"pocket":null,"belt":null,"boots":null,"gloves":null},"inv":{"potion":2,"torch":2,"ration":9,"crypt_cap":2,"wisp_light":1},"xp":297,"relics":[],"xp_next":583,"stress":26,"stress_why":[["nights in the dark",26],["camping out",10],["a night out",-8],["a trap underground",5],["good company",-5],["a song about them",-5]],"fears":[],"food":"ale","habits":[],"hobby":"hiking","hobby_spent":0,"folk":{"thornwall":{"barkeep":4,"smith":6},"carrbridge":{"barkeep":2},"ashfen":{"merchant":4,"barkeep":2}},"diary":[[6,"a merchant with a gold-scale pin paid for Christian's supper and talked prices all through it"],[6,"Christian lies back and talks to Echo about nothing, which turns out to be everything."],[6,"reached level 4 (learned Hammer Down)"],[7,"made camp in a cleared chamber on floor 2 of Goblin Camp and slept with one eye open"],[7,"Christian straightens a bent sword with two rocks and some swearing, right there at Goblin Camp."],[7,"Natasha sings \"The Heron King\" with great conviction. The pitch has gone somewhere else for the night. Echo is very kind about it."],[8,"The bag is empty in Goblin Camp, so Natasha roasts a walking-cap on the end of a spear and shares it out. Nobody asks for seconds, and nobody goes hungry."],[8,"Christian takes Echo's turn on watch without being asked, and doesn't mention it in the morning."],[9,"Nobody has a ration left in Goblin Camp, so Natasha roasts a walking-cap over the fire. It isn't supper, exactly, but nobody goes to bed hungry."],[9,"Christian acts out an old ballad by firelight, playing every part, including the horse."],[9,"Christian knocks together a table from a fallen tree. The crew eats sitting down for the first time in days."],[9,"reached level 6 (learned Carpentry; learned Disarm)"],[10,"The rations ran out in Goblin Camp. Natasha puts a walking-cap on a stick, and that's supper."],[10,"Echo sings \"The Washing-Line Jig\" and loses the tune twice. Each time Christian hands it back.",{"night":"n4","music":true}],[10,"Christian takes Echo's turn on watch without being asked, and doesn't mention it in the morning. Almsgiver, cast gently, for once."],[11,"found a buyer in Thornwall for 7 goblin ears: 13s"],[11,"traded up to an Iron Mace from Dagny for 52s"],[11,"put Natasha's knuckles on the table in one long, slow push"],[12,"sold 1 trinket for 10s"],[12,"Christian thanks the family and moves on with a nod, but a boy runs after him with a drumstick wrapped in a leaf. It is warm."],[12,"At the toll-house parlour, Sabine Venn turns Christian's three cards one at a time: the Two of Cups, the High Priestess and Temperance. Even the candle seems to approve.",{"reading":"r22"}],[13,"The crossing at the Ashfen ferry has a bait tin hung on the post and a sign asking travellers to leave a little for the next angler. Christian adds a worm to the tin.",{"road_rec":"r23"}],[14,"Christian helps an Ashfen roofer for three hours, mostly by holding the ladder. 1 silver."],[15,"Natasha preaches to the crew about sharing. Christian hands over the last biscuit, shamed."],[15,"Echo lies back and talks with Christian about small things, which turn out to be the big ones."],[16,"in the grave-goods store, on the first floor of the Ashveil Crypts: Crates labelled with names. Rings, brooches, small shoes. A few of the crates have been opened in a hurry. Christian is sure there's something here, and is wrong."],[16,"The Two of Cups, said Sabine Venn to Christian four days ago. Someone new came into Christian's life since.",{"reading":"r22"}],[16,"Natasha's Toasted Cheese Trenchers in the Ashveil Crypts come out the wrong colour. They eat them anyway. That was a mistake.",{"meal":"m36"}],[17,"in the crossing of galleries, on the first floor of the Ashveil Crypts: Four galleries meet. In the middle, a stone bench for the tired. A tired thing is sitting on it. Echo counts heads, shakes her head, and they slip past 2 bone constructs, a skeleton archer and risen dead for now."],[17,"woke stiff but rested in the crossing of galleries, and counted it a win"],[17,"Gruk's Victory Ham in the Ashveil Crypts. Christian cooks it like a ceremony, and the crew eat it like one. It comes glazed on the warchief's own shield.",{"meal":"m42"}],[17,"Christian sits with the circlet on and plans three days ahead. It is a good plan."],[17,"reached level 8 (learned Firekeeper; learned Needle and Thread)"],[18,"in the iron-bound door, on the first floor of the Ashveil Crypts: A cold fire at the iron-bound door and a name cut into a beam: The Cobalt Storm. Whatever was here went home in their packs."],[18,"listened to the dark breathe in the iron-bound door on the first floor until the watch changed"],[18,"Christian lays out some Walking-Cap Ragout in the Ashveil Crypts on a flat stone, like a proper table. It is rich, dark and only slightly mobile.",{"meal":"m51"}],[18,"Christian sews a lucky charm into the lining of Natasha's coat. Natasha only finds it a week later. (Needle and Thread, if anyone's asking.)"],[19,"in the nave, on the second floor of the Ashveil Crypts: Rows of pews, and a patient congregation. As one, they turn their heads. The dark keeps its secrets from Echo. Rubbish, mostly, and some of the rubbish is moving."],[19,"Christian touches up his edge at the Ashveil Crypts between fights and tests it on a hair. The hair loses."],[19,"\"Drinking With the Skeleton\" by Echo: wobbly in the middle and grand at the end, with Christian carrying the chorus.",{"night":"n14","music":true}],[19,"reached level 10 (became an Armorer; learned Whetstone)"],[20,"in the weeping room, on the second floor of the Ashveil Crypts: The walls are thick with felt. There's a crying in the room, and nobody in it. Christian is sure there's something here, and is wrong."],[20,"slept the whole night through in the funeral feast hall, boots and all"],[20,"Christian tightens a loose strap on Natasha mid-corridor, without asking, without breaking stride."],[21,"in the family archive, on the second floor of the Ashveil Crypts: Shelves of deeds in oilcloth. A big family tree on the far wall has been scratched out, one branch at a time. Christian reads the papers. They are all about drainage."],[21,"Christian stitches a torn sleeve closed mid-delve at the Ashveil Crypts, holding the thread in his teeth."],[22,"Christian sorts the crew's gear by who dented it, and sends each of them the bill in knuckle-taps. The trick has a name: Hammer and Hold."],[22,"Echo starts \"The Footbridge Dance\" quietly, and by the chorus Natasha and Christian are singing too.",{"night":"n20","music":true}],[22,"reached level 11 (Carpentry, honed)"],[23,"Christian and Echo spend the afternoon in Ashfen fixing each other's gear and arguing about knots."],[24,"It's feast day in Ashfen, and Echo, Natasha and Christian eat some Fen-Mist Chowder at the long tables with half the town. It smells of smoke and the fen at dawn. (8 copper each)",{"meal":"m68"}],[24,"Christian finds the Carrbridge cart at the Ashfen market and tries some Fried River Fish in a Paper Cone, a long way from home. It comes wrapped in last week's tariff notices. (8 copper)",{"meal":"m72"}],[24,"Christian lets the apprentice score on the fourth round. The trainer pretends not to see, and nods."],[24,"Christian tastes an Eel Pie from Widow Marl, then from Tobin the eel-catcher, then from Widow Marl again to be sure, and names Tobin the eel-catcher the better. The other one takes it badly. (1 silver)",{"meal":"m73"}],[25,"let 1 trinket go in Ashfen for 7s"],[25,"bought the Button Checkers in Ashfen for 1 silver 6 copper, dear because it was made elsewhere"],[25,"Natasha offers to check the crew's teeth by firelight. Christian refuses. Natasha will get to Christian eventually."],[25,"Christian hones his blade on a milestone while the crew rests. The milestone looks worse for it. Christian puts it down to Whetstone."],[26,"Natasha cooks some Walking-Cap Ragout in Bleakmarsh while the rest pretend to keep watch. It stopped twitching the moment the garlic went in.",{"meal":"m80"}],[26,"Christian banks the fire so there are still coals at dawn. Breakfast is twenty minutes sooner. Firekeeper all the way, Christian insists."]],"events":[{"id":"e53","day":1,"season":1,"sday":1,"kind":"join","imp":1,"text":"Christian joins the league: a black-clad Warrior, arriving in Ironhaven with 30 silver and Ironroot, grandmother's mace.","heroes":["h19"],"parties":[],"loc":"ironhaven"},{"id":"e67","day":2,"season":1,"sday":2,"kind":"companion","imp":2,"text":"A lone hero and Quill, a clerk walking off a broken heart, share a fire on the road to the Greenwood, and in the morning simply keep walking together.","heroes":["h19"],"parties":[],"loc":"ironhaven"},{"id":"e85","day":3,"season":1,"sday":3,"kind":"party_join","imp":3,"text":"Christian joins The Verdant Sigil over drinks in Thornwall. That makes 3.","heroes":["h19","h6","h11"],"parties":["p2"],"loc":"thornwall","wx":"rain"},{"id":"e86","day":3,"season":1,"sday":3,"kind":"meet","imp":2,"text":"Christian runs into Copper Whiskers on the road between Ironhaven and Thornwall. Stories are exchanged, most of them exaggerated.","heroes":["h19","h13","h9","h7","h5"],"parties":["p1"],"loc":"ironhaven","wx":"rain"},{"id":"e88","day":3,"season":1,"sday":3,"kind":"journey","imp":2,"text":"Christian and The Verdant Sigil share the road to Thornwall. By the second milestone they've agreed on nothing, least of all a shortcut that turned out to be a longcut.","heroes":["h19","h6","h11","h19"],"parties":["p2"]},{"id":"e107","day":4,"season":1,"sday":4,"kind":"talent","imp":2,"text":"Christian beats a dent out of Echo's helmet on a flat rock. It fits better than it did new.","heroes":["h19","h6"],"parties":["p2"],"loc":"goblin_camp","skill":"smith_hands","wx":"rain"},{"id":"e108","day":4,"season":1,"sday":4,"kind":"campfire","imp":1,"text":"Christian asks Echo how Warriors and Rangers are supposed to work together. Neither knows. They work it out.","heroes":["h19","h6"],"parties":["p2"],"loc":"goblin_camp","wx":"rain"},{"id":"e118","day":5,"season":1,"sday":5,"kind":"keepsake","imp":3,"text":"The old map was right. Natasha stands at the mouth of Goblin Camp, the map in one hand, and every turn of it matches.","heroes":["h11","h6","h19"],"parties":["p2"],"loc":"goblin_camp","wx":"rain"},{"id":"e119","day":5,"season":1,"sday":5,"kind":"delve","imp":1,"text":"The Verdant Sigil descends into Goblin Camp, untouched (0%), map in hand.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","wx":"rain"},{"id":"e120","day":5,"season":1,"sday":5,"kind":"fight","imp":3,"text":"First blood for Echo, Natasha and Christian: The Verdant Sigil makes short work of 4 Goblins and a Giant Rat on floor 1 of Goblin Camp. Loot: 6 goblin ears.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","fight":"f10","foes":["goblin","giant_rat","goblin"],"where":"on floor 1 of Goblin Camp","won":true,"close":false,"wx":"rain"},{"id":"e121","day":5,"season":1,"sday":5,"kind":"night","imp":2,"text":"A hooded stranger shares The Verdant Sigil's fire in Goblin Camp, eats half the stew, and says something very specific about Emberdeep before leaving.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","wx":"rain"},{"id":"e130","day":5,"season":1,"sday":5,"kind":"levelups","imp":1,"text":"Level-ups: Garrett to 5 (learned Forager; Forager rank 2); Chloe to 4 (learned Quick Shot; learned Called Shot); Echo to 3 (learned Pinning Shot; learned Evasive); Natasha to 3 (learned Stray Magnet; learned Sermoniser); Christian to 3 (learned Almsgiver; learned Local History).","heroes":["h4","h17","h6","h11","h19"],"parties":[]},{"id":"e132","day":6,"season":1,"sday":6,"kind":"weather","imp":1,"text":"Fog rolls in over the centre. Christian walks into a signpost and apologises to it.","heroes":["h19"],"parties":[],"loc":"ironhaven","wx":"fog"},{"id":"e141","day":6,"season":1,"sday":6,"kind":"fight","imp":1,"text":"The Verdant Sigil makes short work of 2 Goblins and a Goblin Shaman on floor 2 of Goblin Camp. Loot: 5 goblin ears, 3 walking-caps.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","fight":"f14","foes":["goblin","goblin_shaman","goblin"],"where":"on floor 2 of Goblin Camp","won":true,"close":false,"wx":"fog"},{"id":"e170","day":7,"season":1,"sday":7,"kind":"talent","imp":1,"text":"Christian straightens a bent sword with two rocks and some swearing, right there at Goblin Camp.","heroes":["h19"],"parties":["p2"],"loc":"goblin_camp","skill":"smith_hands","wx":"fog"},{"id":"e182","day":8,"season":1,"sday":8,"kind":"treasure","imp":3,"text":"First treasure for Natasha, Echo and Christian: on floor 2 of Goblin Camp, a dead adventurer leaves 66 silver and an unidentified relic, which goes to Christian.","heroes":["h11","h6","h19"],"parties":["p2"],"loc":"goblin_camp","wx":"fog"},{"id":"e198","day":8,"season":1,"sday":8,"kind":"talent","imp":2,"text":"Christian takes Echo's turn on watch without being asked, and doesn't mention it in the morning.","heroes":["h19","h6"],"parties":["p2"],"loc":"goblin_camp","skill":"almsgiver","wx":"fog"},{"id":"e210","day":9,"season":1,"sday":9,"kind":"boss","imp":5,"text":"Down at the bottom of Goblin Camp, The Verdant Sigil slays Gruk the Warchief, a Goblin Archer and a Goblin. Echo's Pinning Shot dropped Gruk, Christian's Hammer Down tied him up, and Echo did the unglamorous work that kept the line from breaking. Loot: 6 goblin ears, 3 trinkets, Gruk's own smoked ham.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","fight":"f25","foes":["goblin_warchief","goblin_archer","goblin"],"where":"at the bottom of Goblin Camp","won":true,"close":false,"wx":"fog"},{"id":"e211","day":9,"season":1,"sday":9,"kind":"treasure","imp":1,"text":"Gruk the Warchief's hoard, counted twice by torchlight: 3 gold pieces and 2 silver.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","in_fight":"f25","wx":"fog"},{"id":"e212","day":9,"season":1,"sday":9,"kind":"night","imp":2,"text":"Echo's ghost story in Goblin Camp ends with \"...and it was standing right behind them.\" Natasha does not look behind her once, all night.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","wx":"fog"},{"id":"e222","day":9,"season":1,"sday":9,"kind":"argument","imp":3,"text":"Whose idea was the last dungeon? Christian and Natasha of The Verdant Sigil settle it with a shouting match.","heroes":["h19","h11"],"parties":["p2"]},{"id":"e226","day":9,"season":1,"sday":9,"kind":"dream","imp":2,"text":"Ask Christian where all this ends and the answer hasn't changed: to slay the dragon of Emberdeep.","heroes":["h19"],"parties":[]},{"id":"e227","day":9,"season":1,"sday":9,"kind":"levelups","imp":1,"text":"Level-ups: Kev to 6 (learned Arm Wrestler; learned Ice Wall); Echo to 6 (learned Hunter's Mark; learned Ice Fishing); Natasha to 6 (learned Aura of Courage; learned Tooth Puller); Christian to 6 (learned Carpentry; learned Disarm); Griffin to 5 (Taunt, honed; learned Sentry); and 3 more.","heroes":["h2","h6","h11","h19","h5"],"parties":[]},{"id":"e228","day":9,"season":1,"sday":9,"kind":"big_move","imp":4,"text":"Gruk the Warchief is down, and the table moves: Echo +56 renown (11th to 2nd), Christian +52 (10th to 3rd) and Natasha +51 (12th to 4th). The Verdant Sigil +107 party renown, 3rd to 1st among the crews.","heroes":["h6","h19","h11"],"parties":["p2"],"cause":"e210","moves":[{"hero":"h6","gain":56,"from":11,"to":2},{"hero":"h19","gain":52,"from":10,"to":3},{"hero":"h11","gain":51,"from":12,"to":4}],"party_moves":[{"party":"p2","gain":107,"from":3,"to":1}],"fight":"f25"},{"id":"e229","day":10,"season":1,"sday":9,"kind":"rework","imp":3,"text":"The old tunnels have shifted, say the guild halls: every lair has new rooms and new tenants, and every map drawn before today is waste paper. Every hero gets a torch, and the 13 who held old maps get bought out.","heroes":["h2","h4","h5","h6","h7","h9","h10","h11","h13","h14","h16","h18","h19"],"parties":[]},{"id":"e241","day":10,"season":1,"sday":10,"kind":"delve_done","imp":1,"text":"The Verdant Sigil comes up for air after 6 days, pockets heavier and boots wetter. They got all the way to the bottom, split 236 silver on the way up and turned back because the rations would only just see them home.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"goblin_camp","days":6,"bottom":true,"rooms":[],"gold":236,"turn":"supplies","wx":"fog"},{"id":"e259","day":10,"season":1,"sday":10,"kind":"talent","imp":1,"text":"Christian takes Echo's turn on watch without being asked, and doesn't mention it in the morning. Almsgiver, cast gently, for once.","heroes":["h19","h6"],"parties":["p2"],"loc":"goblin_camp","skill":"almsgiver","wx":"fog"},{"id":"e281","day":11,"season":1,"sday":11,"kind":"road","imp":3,"text":"On the road to Thornwall, a torn treasure map blows across the path and wraps around Natasha's ankle. It is faded, but Emberdeep is clearly marked.","heroes":["h11","h19","h6"],"parties":["p2"],"road":"goblin_camp~thornwall","road_rec":"r15"},{"id":"e282","day":11,"season":1,"sday":11,"kind":"relic","imp":3,"text":"The temple in Thornwall knows old things: Christian's relic is the Circlet of the Clear Head (sharper, more charming). Christian settles an argument about the cooking rota in one sentence, the circlet cool on his brow.","heroes":["h19"],"parties":[],"loc":"thornwall","wx":"fog"},{"id":"e283","day":11,"season":1,"sday":11,"kind":"bond","imp":2,"text":"Echo and Christian have been seen laughing at The Sagging Beam until the barkeep asked them to stop. Friends, apparently.","heroes":["h6","h19"],"parties":[],"loc":"thornwall","bond":"friends","wx":"fog"},{"id":"e295","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, The Verdant Sigil settles on a goal: to earn 1,150 silver between them before the season ends. \"Eleven hundred and fifty! We're going to need a bigger purse!\" says Natasha.","heroes":["h6","h11","h19"],"parties":["p2"]},{"id":"e323","day":12,"season":1,"sday":12,"kind":"reading","imp":1,"text":"Christian has their cards read for the first time, by Sabine Venn at the toll-house parlour. The High Priestess comes up, and Sabine Venn says Christian has an interesting face for it.","heroes":["h19"],"parties":[],"loc":"carrbridge","reading":"r22","wx":"fog"},{"id":"e324","day":12,"season":1,"sday":12,"kind":"town","imp":2,"text":"A stranger in Carrbridge sells Christian a treasure map for 14 silver. It points to Frostspire, and it might even be real.","heroes":["h19"],"parties":[],"loc":"carrbridge","wx":"fog"},{"id":"e418","day":15,"season":1,"sday":15,"kind":"talent","imp":2,"text":"Natasha preaches to the crew about sharing. Christian hands over the last biscuit, shamed.","heroes":["h11","h19"],"parties":["p2"],"loc":"ashveil_crypts","skill":"sermoniser","wx":"fog"},{"id":"e470","day":16,"season":1,"sday":16,"kind":"delve","imp":1,"text":"The Verdant Sigil lights the first torch at the mouth of the Ashveil Crypts. The place is mostly unexplored (26%).","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts"},{"id":"e492","day":16,"season":1,"sday":16,"kind":"meet","imp":2,"text":"Echo and Garrett compare boots, then blisters, then regrets, at the Ashveil Crypts.","heroes":["h6","h11","h19","h17","h4"],"parties":["p2","p4"],"loc":"ashveil_crypts"},{"id":"e495","day":16,"season":1,"sday":16,"kind":"omen_true","imp":2,"text":"The Two of Cups, said Sabine Venn to Christian four days ago. Someone new came into Christian's life since.","heroes":["h19"],"parties":[],"loc":"ashveil_crypts","reading":"r22"},{"id":"e496","day":16,"season":1,"sday":16,"kind":"cooking","imp":1,"text":"Natasha's Toasted Cheese Trenchers in the Ashveil Crypts come out the wrong colour. They eat them anyway. That was a mistake.","heroes":["h6","h11","h19"],"parties":[],"loc":"ashveil_crypts","meal":"m36"},{"id":"e500","day":16,"season":1,"sday":16,"kind":"campfire","imp":1,"text":"Christian mends Natasha's bootlace with a bit of string and a great deal of confidence.","heroes":["h19","h11"],"parties":["p2"],"loc":"ashveil_crypts"},{"id":"e507","day":17,"season":1,"sday":17,"kind":"fight","imp":2,"text":"It takes the Verdant Sigil 6 rounds to scrape past 3 Skeletons and Risen Dead in the coffin racks on the first floor of the Ashveil Crypts. Echo took the last shot with Thorn Whip, and it was enough. Natasha never wasted a move, start to finish. Loot: 10 bones, 4 trinkets, 7 crypt-caps.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts","fight":"f49","foes":["skeleton","skeleton","zombie"],"where":"in the coffin racks on the first floor of the Ashveil Crypts","won":true,"close":true,"shape":"close","reworded":-20},{"id":"e532","day":17,"season":1,"sday":17,"kind":"cooking","imp":3,"text":"Gruk's Victory Ham in the Ashveil Crypts, glazed on the warchief's own shield: Christian cooks it like a ceremony, and the crew eat it like one.","heroes":["h6","h11","h19"],"parties":[],"loc":"ashveil_crypts","meal":"m42"},{"id":"e533","day":17,"season":1,"sday":17,"kind":"campfire","imp":2,"text":"Two weeks on the road together: Echo and Christian now finish each other's complaints.","heroes":["h6","h19"],"parties":["p2"],"loc":"ashveil_crypts"},{"id":"e537","day":17,"season":1,"sday":17,"kind":"ambition","imp":5,"text":"Christian has now set foot in four of the realm's towns this season, and it goes in the Annals in ink. He gives it a day before setting a new mark: to hold a record in the Creel Book.","heroes":["h19"],"parties":[],"ambition":"explorer"},{"id":"e572","day":18,"season":1,"sday":18,"kind":"cooking","imp":1,"text":"Christian lays out some Walking-Cap Ragout in the Ashveil Crypts on a flat stone, like a proper table. It is rich, dark and only slightly mobile.","heroes":["h6","h11","h19"],"parties":[],"loc":"ashveil_crypts","meal":"m51"},{"id":"e573","day":18,"season":1,"sday":18,"kind":"bond","imp":2,"text":"Christian and Natasha finish each other's complaints now. Friends, the grumbling kind.","heroes":["h19","h11"],"parties":[],"loc":"ashveil_crypts","bond":"friends"},{"id":"e574","day":18,"season":1,"sday":18,"kind":"talent","imp":2,"text":"Christian sews a lucky charm into the lining of Natasha's coat. Natasha only finds it a week later. (Needle and Thread, if anyone's asking.)","heroes":["h19","h11"],"parties":["p2"],"loc":"ashveil_crypts","skill":"tailor"},{"id":"e593","day":19,"season":1,"sday":19,"kind":"evolve","imp":4,"text":"Christian the Warrior becomes an Armorer, after a career heavy on Needle and Thread and Carpentry. First new trick: Anvil Drop, and the guild sends over a Smith's Hammer to go with it.","heroes":["h19"],"parties":[],"cls_from":"warrior","cls_to":"armorer"},{"id":"e594","day":19,"season":1,"sday":19,"kind":"fight","imp":2,"text":"The Verdant Sigil runs into 3 Skeletons and a Skeleton Archer in the choir loft on the second floor of the Ashveil Crypts and comes out on top. The skeleton met Natasha's Smite and lay down for good. Loot: 16 bones.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts","fight":"f52","foes":["skeleton_archer","skeleton","skeleton"],"where":"in the choir loft on the second floor of the Ashveil Crypts","won":true,"close":false,"shape":"plain","reworded":-23},{"id":"e597","day":19,"season":1,"sday":19,"kind":"keystone","imp":1,"text":"Christian reaches level 10 and gains Hammer and Hold: when he drops low in a fight, he hammers a dent out of every ally's armour on the spot. It grew out of Smith's Hands and Hammer Down.","heroes":["h19"],"parties":[],"keystone":"hammer_and_hold","ks":"Hammer and Hold","level":10},{"id":"e598","day":19,"season":1,"sday":19,"kind":"fight","imp":2,"text":"It's 3 Skeletons and a Skeleton Archer against the Verdant Sigil in the nave on the second floor of the Ashveil Crypts, and it isn't close. The hit of the day was Echo's Patient Shot on the skeleton. Christian did the quiet, necessary things, and most of the loud ones too. Loot: 14 bones, 2 trinkets.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts","fight":"f53","foes":["skeleton","skeleton_archer","skeleton"],"where":"in the nave on the second floor of the Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-24},{"id":"e607","day":19,"season":1,"sday":19,"kind":"song","imp":3,"text":"\"Here Comes Christian\" gets a try-out at The Watching Oak on a quiet night. It's about Christian's long dark week in the Ashveil Crypts, more or less, and the night isn't quiet for long.","heroes":["h19"],"parties":[],"loc":"hollowood","song":"s19_12"},{"id":"e611","day":19,"season":1,"sday":19,"kind":"talent","imp":1,"text":"Christian touches up his edge at the Ashveil Crypts between fights and tests it on a hair. The hair loses.","heroes":["h19"],"parties":["p2"],"loc":"ashveil_crypts","skill":"whetstone"},{"id":"e619","day":19,"season":1,"sday":19,"kind":"levelups","imp":1,"text":"Level-ups: Echo to 10 (learned Trapper; became a Sharpshooter; learned Trick Shot); Natasha to 10 (became a Paladin; learned Oath of Light); Christian to 10 (became an Armorer; learned Whetstone); Chloe to 8 (Rain of Arrows, honed).","heroes":["h6","h11","h19","h17"],"parties":[]},{"id":"e627","day":20,"season":1,"sday":20,"kind":"famous_trap","imp":3,"text":"The Ashveil Crypts have a new tenant and The Ninth Step a fresh victim: Christian, with a cracked collarbone, the first it has caught since the change of management.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts"},{"id":"e628","day":20,"season":1,"sday":20,"kind":"fight","imp":1,"text":"With Natasha hitting hardest, the Verdant Sigil dispatches a Skeleton Archer, Risen Dead and a Skeleton in the funeral feast hall on the second floor of the Ashveil Crypts. Everything after Christian's Hammer Down went right. Oath of Light woke up in Natasha at just the right time. Loot: 8 bones.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts","fight":"f55","foes":["skeleton_archer","zombie","skeleton"],"where":"in the funeral feast hall on the second floor of the Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-30},{"id":"e641","day":20,"season":1,"sday":20,"kind":"talent","imp":1,"text":"Christian tightens a loose strap on Natasha mid-corridor, without asking, without breaking stride.","heroes":["h19","h11"],"parties":["p2"],"loc":"ashveil_crypts","skill":"hammer_and_hold"},{"id":"e668","day":21,"season":1,"sday":21,"kind":"song","imp":2,"text":"By the time \"Here Comes Christian\" reaches Carrbridge, half the names in it are wrong and the fight in it is twice as long.","heroes":["h19"],"parties":[],"loc":"carrbridge","song":"s19_12","wx":"rain"},{"id":"e669","day":21,"season":1,"sday":21,"kind":"night_game","imp":2,"text":"A goblin appears out of nowhere to challenge Echo at checkers, and leaves with the Button Checkers.","heroes":["h6","h11","h19"],"parties":[],"loc":"ashveil_crypts"},{"id":"e684","day":22,"season":1,"sday":22,"kind":"party_life","imp":3,"text":"Echo stopped at the top of the stair down from the second floor and would not be moved, so The Verdant Sigil turns for the surface and a late breakfast.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts","nerve":"h6"},{"id":"e685","day":22,"season":1,"sday":22,"kind":"delve_done","imp":3,"text":"The Ashveil Crypts hands The Verdant Sigil back after 7 days, dusty and squinting. They reached the second floor, turned up The Ninth Step, the bell chamber and the reliquary, cleared 13 rooms, put 40% of it on paper, split 123 silver on the way up and turned back when Echo would go no further. Counting every crew that has been down, the Ashveil Crypts is partly explored (48%).","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts","days":7,"bottom":false,"rooms":["The Ninth Step","the bell chamber"],"gold":123,"turn":"nerve"},{"id":"e686","day":22,"season":1,"sday":22,"kind":"talent","imp":2,"text":"Christian sorts the crew's gear by who dented it, and sends each of them the bill in knuckle-taps. The trick has a name: Hammer and Hold.","heroes":["h19"],"parties":["p2"],"loc":"ashveil_crypts","skill":"hammer_and_hold"},{"id":"e709","day":22,"season":1,"sday":22,"kind":"bond","imp":4,"text":"Where you find Echo now, you'll find Christian: best friends, never seen apart and always in trouble together.","heroes":["h6","h19"],"parties":[],"loc":"ashveil_crypts","bond":"best friends"},{"id":"e720","day":23,"season":1,"sday":23,"kind":"road","imp":3,"text":"Supper on the road: Marigold sets up the pot, Echo is given the spoon to hold, and the smell makes the miles ahead seem short.","heroes":["h6","h11","h19"],"parties":["p2"],"road":"ashfen~ashveil_crypts","biome":"marsh","traveller":"marigold","road_rec":"r97"},{"id":"e724","day":23,"season":1,"sday":23,"kind":"sale","imp":1,"text":"Christian empties his pack onto a counter in Ashfen: 29 bones. 34 silver.","heroes":["h19"],"parties":[],"loc":"ashfen","amount":34},{"id":"e725","day":23,"season":1,"sday":23,"kind":"healed","imp":1,"text":"Christian is back to full strength, and the bandages from the cracked collarbone go on the fire.","heroes":["h19"],"parties":[]},{"id":"e742","day":23,"season":1,"sday":23,"kind":"song","imp":1,"text":"At The Damp Lantern, Christian sits at the back through \"Here Comes Christian\" and tells nobody who it's about. Everybody knows.","heroes":["h19"],"parties":[],"loc":"ashfen","song":"s19_12"},{"id":"e749","day":23,"season":1,"sday":23,"kind":"dream","imp":2,"text":"Ask Christian where all this ends and the answer hasn't changed: to hold a record in the Creel Book.","heroes":["h19"],"parties":[]},{"id":"e758","day":24,"season":1,"sday":24,"kind":"cooking","imp":2,"text":"It's feast day in Ashfen, and Echo, Natasha and Christian eat some Fen-Mist Chowder at the long tables with half the town. It smells of smoke and the fen at dawn. (8 copper each)","heroes":["h6","h11","h19"],"parties":[],"loc":"ashfen","meal":"m68"},{"id":"e790","day":25,"season":1,"sday":25,"kind":"contract","imp":2,"text":"The Verdant Sigil takes a clearing job in Ashfen: 10 will-o'-wisps out of Bleakmarsh by day 3 of next season.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashfen"},{"id":"e808","day":25,"season":1,"sday":25,"kind":"boss_race","imp":2,"text":"The Verdant Sigil is out of the race for Vessimir the Unburied: they have taken a clearing job in Bleakmarsh. That leaves The Royal Vigil.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"ashveil_crypts"},{"id":"e815","day":25,"season":1,"sday":25,"kind":"campfire","imp":3,"text":"Christian shows Echo how to oil a scabbard properly. Echo pretends to know already, then takes notes.","heroes":["h19","h6"],"parties":["p2"],"loc":"bleakmarsh"},{"id":"e823","day":26,"season":1,"sday":26,"kind":"fight","imp":1,"text":"In Bleakmarsh, 2 Will-o'-Wisps get in the Verdant Sigil's way, briefly. The others will tell it differently, but the fight changed on Christian's Hammer Down. Echo's Ambush looked after itself, and the fight with it. Loot: 2 bottled wisplight.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"bleakmarsh","fight":"f64","foes":["wisp","wisp"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"place","reworded":-15},{"id":"e825","day":26,"season":1,"sday":26,"kind":"night","imp":2,"text":"A soldier with old wounds sits at The Verdant Sigil's fire in Bleakmarsh and talks about Goblin Camp until the fire is ash. He was there once. He won't say when.","heroes":["h6","h11","h19"],"parties":["p2"],"loc":"bleakmarsh"},{"id":"e839","day":26,"season":1,"sday":26,"kind":"meet","imp":2,"text":"With The Verdant Sigil and The Azure Stallions sharing a fire in Bleakmarsh, the watches split nicely and everyone sleeps a little better.","heroes":["h6","h11","h19","h3","h12","h14","h18"],"parties":["p2","p5"],"loc":"bleakmarsh"}],"rels":[{"hero":"h6","score":100,"bond":"best friends","mentor":null,"mate":true},{"hero":"h11","score":74,"bond":"friends","mentor":null,"mate":true},{"hero":"h14","score":43,"bond":null,"mentor":null,"mate":false},{"hero":"h18","score":42,"bond":null,"mentor":null,"mate":false},{"hero":"h12","score":16,"bond":null,"mentor":null,"mate":false},{"hero":"h3","score":7,"bond":null,"mentor":null,"mate":false},{"hero":"h10","score":6,"bond":null,"mentor":null,"mate":false},{"hero":"h9","score":6,"bond":null,"mentor":null,"mate":false}],"debts":[],"season":{"kills":7,"bosses":1,"gold_earned":203,"dmg":476,"healed":0,"fights":8,"wins":8,"fled":0,"downed":0,"levels":10,"loot_sold":64,"days_worked":0,"delves":2,"floors":4,"pvp_wins":0,"pvp_losses":0,"robbed":0,"robberies":0,"injuries":1,"contracts":0,"travel_days":10,"renown":28,"corpses_sold":0,"best_sale":34,"deaths_witnessed":0,"gambled":0,"bounties":12,"best_day":52,"taken":114,"steady":0.6600000000000001,"band_delves":1.333,"band_floors":2.666,"band_kills":9.666},"season_closed":false,"career":{"kills":7,"bosses":1,"gold_earned":203,"dmg":476,"healed":0,"fights":8,"wins":8,"fled":0,"downed":0,"levels":10,"loot_sold":64,"days_worked":0,"delves":2,"floors":4,"pvp_wins":0,"pvp_losses":0,"robbed":0,"robberies":0,"injuries":1,"contracts":0,"travel_days":10,"renown":28,"corpses_sold":0,"best_sale":34,"deaths_witnessed":0,"gambled":0,"bounties":12,"best_day":52,"taken":114,"steady":0.6600000000000001,"band_delves":1.333,"band_floors":2.666,"band_kills":9.666},"past":[],"profile":{"maxhp":140,"pow":45.1,"arm":5,"acc":82,"eva":11,"crit":8,"spd":6,"resolve":26,"thorns":0,"vs_big":0,"vs":{},"onhit":[],"lifesteal":0.0,"mind_stat":14,"heart_stat":10,"might":17},"town_rep":{"thornwall":4,"ashfen":3},"regular":{"thornwall":2,"ashfen":1},"jobs":{},"remains_of":[],"death_cause":null,"death_place":null,"buried":null,"memorial_at":null,"body":null,"quiz":["Christian","Christian",0,1,5,2,1,8,0,1,2,0,1,0,2,0,5,4,1,4,0],"ambition":"to hold a record in the Creel Book","ambitions_done":["to set foot in four of the realm's towns in one season"],"visited":["ironhaven","thornwall","carrbridge","ashfen"],"tonight":{"setting":"camp","room":null,"biome":"marsh","road":false,"floor":null,"theme":null,"host":null,"others":[],"place":"Camped out at Bleakmarsh","cast":[{"id":"h19","lines":["We saw off some trouble in Bleakmarsh. Moving on.","Keep the fire low.","We move at dawn.","This season we're out to earn 1,150 silver between us before the season ends: 332 of 1,150 silver.","The plan hasn't changed: I'm going to hold a record in the Creel Book.","I miss hiking.","Echo has my back."],"pet":[]},{"id":"h6","lines":["We saw off some trouble in Bleakmarsh. I don't know how to feel.","I'm not sleeping. I'll just lie here.","{shake}What was that?{/} Did you hear that?","This season we're out to earn 1,150 silver between us before the season ends: 332 of 1,150 silver.","I want to have four true friends. Is that silly?","Nobody mention deep water tonight.","I miss flea markets.","Natasha has my back."],"pet":[]},{"id":"h11","lines":["Varun and I are friends now. Best day!","They've started calling me \"Everyone's-Friend\". Best day!","Camping is the {slam}BEST{/}.","{wave}Ghost stories!{/} Who's first?","This season we're out to earn 1,150 silver between us before the season ends: 332 of 1,150 silver.","One day I'm going to write a song! Wait and see!","Nobody mention fire tonight.","I miss throwing parties.","Echo is my favourite!"],"pet":[]}],"talk":[[{"id":"h6","text":"Not a bad day's work, Natasha."},{"id":"h11","text":"Right?! Best day ever."}],[{"id":"h19","text":"Shooting from back there must be relaxing."},{"id":"h6","text":"Was that a joke? That was a joke."}],[{"id":"h11","text":"Show me Hammer Down sometime, Christian?"},{"id":"h19","text":"First light. Bring water."}]],"mounts":[],"wagon":null}};